import json

Q = []
def add(qid, prompt, opts, correct, expl, topic, diff="intermediate"):
    Q.append({
        "id": qid, "type": "single_choice", "prompt": prompt, "stimulus": {"text": ""},
        "options": [{"id": L, "text": T} for L, T in opts],
        "answer": {"correctOptionIds": [correct], "explanation": expl},
        "difficulty": diff, "topicIds": [topic], "sectionIds": [], "learningObjectiveIds": [],
        "examCategories": [], "origin": "source", "sourceReferences": [{"page": 1}],
        "reviewStatus": "needs_review",
    })

